const $=id=>document.getElementById(id);
function nav(tab){document.querySelectorAll("nav button").forEach(b=>b.classList.toggle("active",b.dataset.tab===tab));document.querySelectorAll(".section").forEach(s=>s.classList.toggle("active",s.id===tab));if(tab==="shopping")renderShopping();}
document.querySelectorAll("nav button").forEach(b=>b.addEventListener("click",()=>nav(b.dataset.tab)));
const categories=["All","Vegan","Vegetarian"];
let activeCategory="All", planner={}, checked=new Set();
const isVegan=r=>r.vegan===undefined ? ![15,18].includes(r.id) : r.vegan;
function renderFilters(){const all=[...categories,...new Set(recipes.map(r=>r.category).filter(Boolean))];$("filters").innerHTML=all.map(c=>`<button class="chip ${c===activeCategory?'active':''}" onclick="activeCategory=${JSON.stringify(c)};renderFilters();renderRecipes()">${c}</button>`).join("")}
function recipeCard(r){return `<article class="card"><div class="food-art" style="background:#e7eadf;padding:0"><img src="${r.image}" alt="${r.name}" loading="lazy" style="width:100%;height:180px;object-fit:cover;display:block" onerror="this.onerror=null;this.remove();this.parentElement.innerHTML='<div class="photo-pending">Dish photograph in production</div>'"></div><div class="card-body"><div class="card-top"><span class="tag">${r.category} · ${isVegan(r)?"Vegan":"Vegetarian"}</span><span class="protein">${r.protein}<small style="font:11px system-ui"> g protein</small></span></div><h3>${r.name}</h3><div class="meta"><span>${r.cal} kcal</span><span>${r.carbs} g carbs</span><span>${r.fiber} g fibre</span><span>${r.mins} min</span></div><div class="card-actions"><button class="btn primary small" onclick="openRecipe(${r.id})">View recipe</button></div></div></article>`}
function renderRecipes(){let list=recipes.filter(r=>activeCategory==="All"||(activeCategory==="Vegan"&&isVegan(r))||(activeCategory==="Vegetarian"&&!isVegan(r))||r.category===activeCategory);$("recipeGrid").innerHTML=list.map(recipeCard).join("")||"<p>No recipes in this category yet.</p>"}
function openRecipe(id){let r=recipes.find(x=>x.id===id);$("modalContent").innerHTML=`<div class="eyebrow">${r.category} · ${r.mins} minutes · Serves 2</div><h2 style="font:36px Georgia;color:var(--forest);margin:8px 0 16px">${r.name}</h2><img src="${r.image}" alt="${r.name}" style="width:100%;height:230px;object-fit:cover;border-radius:14px;margin-bottom:16px"><div class="metrics"><div class="metric"><b>${r.protein} g</b><span>Protein</span></div><div class="metric"><b>${r.cal}</b><span>Calories</span></div><div class="metric"><b>${r.carbs} g</b><span>Carbohydrates</span></div><div class="metric"><b>${r.fiber} g</b><span>Fibre</span></div></div><div class="recipe-layout"><div><h3>Ingredients · Serves 2</h3><ul>${r.ingredients.map(x=>`<li>${x}</li>`).join("")}</ul></div><div><h3>Stovetop method</h3><ol>${r.steps.map(x=>`<li>${x}</li>`).join("")}</ol></div></div><h3 style="font:22px Georgia;color:var(--forest);margin-top:24px">Four ways to cook</h3><div class="recipe-layout"><div class="note"><b>Microwave · about ${Math.max(8,Math.round(r.cook*.75))} min</b><br>Use a microwave-safe covered dish with a vent. Add 1–2 tbsp water or stock, heat in short intervals and stir midway. Rest covered for 2 minutes; check the centre is steaming hot. Dense pulses and raw root vegetables need longer and should be pre-cooked where necessary.</div><div class="note"><b>Conventional oven · about ${Math.max(15,Math.round(r.cook*1.15))} min</b><br>Preheat to 190°C / 375°F. Transfer to a covered oven-safe dish for curries or spread in a single layer for dry dishes. Stir or turn halfway and cook until the centre is hot and ingredients are tender. Add a splash of liquid if drying out.</div><div class="note"><b>Air fryer · about ${Math.max(8,Math.round(r.cook*.8))} min</b><br>Preheat to 180°C / 350°F. Best for cut vegetables, patties and tofu; use an air-fryer-safe dish for saucy foods. Arrange in a single layer, turn or shake halfway and check for even browning and full doneness. For dal or curry, use stovetop or microwave instead.</div><div class="note"><b>Stovetop · ${r.cook} min cooking + ${r.prep} min prep</b><br>Follow the step-by-step method above. Total kitchen time: approximately ${r.mins} minutes. Times are practical starting estimates and vary with appliance wattage, food size, batch size and whether pulses or grains are pre-cooked.</div></div>${(r.sourceReferences?.length||recipeReferences[r.id])?`<div class="note" style="margin-top:16px"><b>Recipe references & adaptation notes</b><ul>${(r.sourceReferences||recipeReferences[r.id]||[]).map(x=>`<li><a href="${x[1]}" target="_blank" rel="noopener">${x[0]}</a> — ${x[2]}</li>`).join("")}</ul></div>`:""}<div class="note"><b>Nutrition note</b><br>${r.note}<br><br><b>Recipe provenance:</b> See the individual reference note where supplied. Where no recipe-specific reference is listed, source tracing and rights review are still pending; do not treat this entry as verified original or cleared for republication. <a href="https://nin.res.in/dietaryguidelines/pdfjs/locale/DGI_2024.pdf" target="_blank" rel="noopener">ICMR-NIN Dietary Guidelines (2024)</a> · <a href="https://www.nutrition.va.gov/NUTRITION/docs/Cookbooks/PracticalPlantBasedCookingMAY2023.pdf" target="_blank" rel="noopener">VA Practical Plant-Based Cooking</a> · <a href="https://www.fssai.gov.in/book-details.php?bkid=348" target="_blank" rel="noopener">FSSAI Pink Book</a><br><br><b>Estimated fat:</b> ${r.fat} g per serving. Saturated fat and natural sugars are not fully calculated in this starter edition. Added sugar is not included in the recipe.</div><div style="display:flex;gap:10px;flex-wrap:wrap;margin-top:16px"><button class="btn primary" onclick="addToPlanner(${r.id});closeModal()">Add to weekly planner</button><button class="btn" onclick="window.print()">Print recipe</button></div>`;$("modal").classList.add("open")}
function closeModal(){$("modal").classList.remove("open")}
function addToPlanner(id){nav("planner");let day=Object.keys(planner).find(d=>!planner[d]?.lunch)||"Monday";planner[day]=planner[day]||{};planner[day].lunch=id;renderPlanner()}
const days=["Monday","Tuesday","Wednesday","Thursday","Friday","Saturday","Sunday"];
function renderPlanner(){let options='<option value="">Choose a recipe…</option>'+recipes.map(r=>`<option value="${r.id}">${r.name} · ${r.protein}g protein</option>`).join("");$("plannerGrid").innerHTML=days.map(d=>`<div class="day"><h3>${d}</h3>${["lunch","dinner"].map(m=>`<div class="meal"><label>${m}</label><select onchange="setMeal('${d}','${m}',this.value)">${options.replace(`value="${planner[d]?.[m]||''}"`,`value="${planner[d]?.[m]||''}" selected`)}</select></div>`).join("")}<div class="sub" id="sum-${d}"></div></div>`).join("");let total=0,count=0;days.forEach(d=>{let p=0;["lunch","dinner"].forEach(m=>{let r=recipes.find(x=>x.id===Number(planner[d]?.[m]));if(r){p+=r.protein;total+=r.protein;count++}});$("sum-"+d).textContent=`Planned recipe protein: ${p} g`;});$("plannedMeals").textContent=count;$("plannedProtein").textContent=Math.round(total/7)+" g";renderShopping()}
function setMeal(d,m,v){planner[d]=planner[d]||{};if(v)planner[d][m]=Number(v);else delete planner[d][m];renderPlanner()}
function selectedRecipes(){let ids=days.flatMap(d=>["lunch","dinner"].map(m=>planner[d]?.[m]).filter(Boolean));return [...new Set(ids)].map(id=>recipes.find(r=>r.id===id)).filter(Boolean)}
function renderShopping(){let items={};selectedRecipes().forEach(r=>r.ingredients.forEach(i=>{let key=i.split(",")[0].toLowerCase().trim();items[key]=i}));let vals=Object.values(items);$("shoppingCount").textContent=vals.length+" ingredients";$("shoppingList").innerHTML=vals.length?vals.map((v,i)=>`<label><input type="checkbox" ${checked.has(v)?"checked":""} onchange="this.checked?checked.add(${JSON.stringify(v)}):checked.delete(${JSON.stringify(v)})"><span>${v}</span></label>`).join(""):"<p class='muted'>Choose lunch or dinner recipes in the weekly planner to generate your shopping list.</p>"}
function copyShopping(){let text=Object.values(Object.fromEntries(selectedRecipes().flatMap(r=>r.ingredients.map(i=>[i.split(",")[0].toLowerCase().trim(),i])))).join("\
");if(navigator.clipboard?.writeText)navigator.clipboard.writeText(text).then(()=>alert("Shopping list copied."));else alert(text||"Add recipes to your planner first.")}
function updateTracker(){let goal=Math.max(1,Number($("goal").value)||100),total=["breakfast","lunch","dinner","snacks"].reduce((s,id)=>s+(Number($(id).value)||0),0),pct=Math.min(100,total/goal*100);$("proteinTotal").textContent=total+" g consumed";$("proteinRemaining").textContent=Math.max(0,goal-total)+" g to goal";$("proteinBar").style.width=pct+"%";$("proteinMessage").textContent=total>=goal?"You've reached your entered protein target.":`You've logged ${Math.round(pct)}% of your entered daily target.`}
["goal","breakfast","lunch","dinner","snacks"].forEach(id=>$(id).addEventListener("input",updateTracker));

