const curatedBreakfasts = [
{id:26,name:"Moong Dal Chilla",category:"Healthy Indian Breakfasts",protein:18,cal:285,carbs:34,fiber:8,fat:7,mins:35,prep:20,cook:15,ingredients:["¾ cup split yellow moong dal, rinsed and soaked 3–4 hours","¼ cup water, plus more as needed","½ cup finely chopped spinach","¼ small onion, finely chopped","1 green chilli, minced (optional)","½ tsp grated ginger","¼ tsp cumin seeds","¼ tsp turmeric","2 tsp neutral oil, divided","2 tbsp chopped coriander","Salt to taste"],steps:["Drain the soaked dal. Blend with ¼ cup water, ginger, turmeric and salt to a smooth, thick pourable batter.","Fold in spinach, onion, chilli, cumin and coriander. Rest 5 minutes; add a spoonful of water only if the batter is too thick to spread.","Heat a non-stick skillet over medium heat and brush with a little oil. Pour half the batter and spread into a 15–16 cm circle.","Cook 2–3 minutes until the top looks set and the underside is golden. Flip, brush the edge with a little oil and cook 1–2 minutes more.","Repeat with the remaining batter. Serve hot with coriander chutney and plain soy yogurt."],note:"Soaking softens the dal for blending. Keep the batter thick so the chillas turn easily. Nutrition is an estimate for the full two-chilla serving.",vegan:true},
{id:27,name:"Besan Vegetable Cheela",category:"Healthy Indian Breakfasts",protein:16,cal:275,carbs:31,fiber:7,fat:9,mins:25,prep:10,cook:15,ingredients:["¾ cup besan (chickpea flour)","½ cup water, approximately","¼ cup grated carrot","¼ cup finely chopped capsicum","2 tbsp chopped onion","1 tbsp chopped coriander","¼ tsp ajwain","¼ tsp turmeric","¼ tsp ground cumin","2 tsp oil","Salt and chilli to taste"],steps:["Whisk besan, water, turmeric, cumin, ajwain and salt until smooth; rest 5 minutes.","Stir in carrot, capsicum, onion and coriander. The batter should fall slowly from a spoon; adjust with a little water.","Heat a non-stick pan over medium. Lightly oil, pour half the batter and spread to a thin 15 cm round.","Cook 2–3 minutes until the edges lift and the base is golden. Flip and cook another 2 minutes.","Cook the second cheela. Serve with mint-coriander chutney; avoid adding sugary sauces."],note:"Use a well-heated non-stick pan and spread the batter evenly for a tender centre and crisp edges.",vegan:true},
{id:28,name:"Vegetable Oats Upma",category:"Healthy Indian Breakfasts",protein:13,cal:290,carbs:43,fiber:8,fat:8,mins:20,prep:8,cook:12,ingredients:["1 cup rolled oats","1½ cups water","½ cup diced mixed vegetables (carrot, peas and beans)","2 tbsp chopped onion","1 tsp oil","½ tsp mustard seeds","½ tsp cumin seeds","1 tbsp roasted unsalted sunflower seeds","6 curry leaves","1 green chilli, slit (optional)","Lemon juice, coriander and salt"],steps:["Toast oats in a dry pan for 2–3 minutes until fragrant; transfer to a bowl.","Heat oil in the pan. Add mustard, cumin, curry leaves and chilli; let the seeds pop.","Add onion and vegetables. Cook 3–4 minutes, stirring, until they begin to soften.","Add water and salt. Bring to a simmer, then stir in oats.","Cook 3–4 minutes until creamy but not mushy. Finish with lemon, coriander and sunflower seeds."],note:"Rolled oats cook quickly; steel-cut oats need a different liquid ratio and longer cooking.",vegan:true},
{id:29,name:"Vegetable Poha with Peas",category:"Healthy Indian Breakfasts",protein:12,cal:285,carbs:46,fiber:5,fat:7,mins:20,prep:10,cook:10,ingredients:["1½ cups thick poha","½ cup green peas, fresh or frozen","¼ cup diced carrot","2 tbsp chopped onion","1 tsp oil","½ tsp mustard seeds","¼ tsp turmeric","6 curry leaves","1 tbsp roasted pumpkin seeds","½ lemon","Coriander and salt"],steps:["Place poha in a sieve and rinse briefly under running water. Drain thoroughly; season lightly with salt and turmeric.","Heat oil; add mustard seeds and curry leaves. Add onion and carrot and cook 3 minutes.","Add peas and 2 tbsp water; cover for 2–3 minutes until tender.","Fold in softened poha gently. Cover on low heat for 2 minutes, then turn off the heat.","Finish with lemon, coriander and pumpkin seeds. Fluff with a fork and serve."],note:"Rinse thick poha quickly rather than soaking it; over-soaking makes it sticky.",vegan:true},
{id:30,name:"Ragi Onion Dosa",category:"Healthy Indian Breakfasts",protein:11,cal:260,carbs:42,fiber:6,fat:6,mins:25,prep:8,cook:17,ingredients:["¾ cup ragi (finger millet) flour","¼ cup rice flour","2 tbsp plain unsweetened soy yogurt","1½ cups water, approximately","¼ small onion, finely chopped","1 tbsp chopped coriander","¼ tsp cumin seeds","1 tsp oil for the pan","Salt to taste"],steps:["Whisk ragi flour, rice flour, soy yogurt, cumin, salt and water into a thin, lump-free batter.","Rest 10 minutes. Stir in onion and coriander; add water if needed for a pourable consistency.","Heat a seasoned non-stick dosa pan over medium-high and wipe with a little oil.","Pour a ladle of batter from the outside inward; do not spread like a thick pancake. Drizzle a few drops of oil around the edge.","Cook 2–3 minutes until the edges lift and the base is crisp. Fold and serve; repeat."],note:"Ragi dosa is naturally gluten-free when all packaged ingredients are certified gluten-free. The batter is thinner than regular dosa batter.",vegan:true},
{id:31,name:"Tofu Bhurji Breakfast",category:"Healthy Indian Breakfasts",protein:23,cal:285,carbs:17,fiber:5,fat:15,mins:18,prep:7,cook:11,ingredients:["200 g firm tofu, drained and crumbled","¼ small onion, finely chopped","½ tomato, deseeded and chopped","½ cup chopped spinach","1 tsp oil","¼ tsp cumin seeds","¼ tsp turmeric","¼ tsp coriander powder","Pinch of garam masala","1 tbsp coriander and lemon"],steps:["Pat tofu dry and crumble into small pieces with a fork.","Heat oil in a skillet. Add cumin and onion; cook 2 minutes until translucent.","Add tomato, turmeric and coriander powder; cook until tomato softens.","Add spinach and cook until wilted. Fold in tofu and garam masala.","Cook 3–4 minutes, stirring gently. Finish with coriander and lemon; serve with one small whole-wheat roti."],note:"Choose calcium-set tofu where available. Nutrition estimate covers the tofu bhurji only, not the optional roti.",vegan:true},
{id:32,name:"Sprouted Moong Breakfast Bowl",category:"Healthy Indian Breakfasts",protein:19,cal:275,carbs:39,fiber:10,fat:6,mins:20,prep:10,cook:10,ingredients:["1½ cups mung bean sprouts","½ cup diced cucumber","½ cup diced tomato","¼ cup grated carrot","½ cup plain unsweetened soy yogurt","1 tbsp lemon juice","½ tsp roasted cumin powder","2 tbsp chopped coriander","1 tbsp roasted sunflower seeds","Salt and black pepper"],steps:["Steam or boil sprouts for 5–7 minutes until piping hot and tender; cool slightly. Do not use raw sprouts for people at higher risk of foodborne illness.","Whisk soy yogurt with lemon, cumin, salt and pepper to make a dressing.","Divide warm sprouts between two bowls. Add cucumber, tomato and carrot.","Spoon over the dressing and toss lightly.","Finish with coriander and sunflower seeds. Serve promptly."],note:"Sprouts are perishable. Refrigerate promptly and cook thoroughly rather than serving raw, especially for pregnant, older or immunocompromised people.",vegan:true},
{id:33,name:"Masala Vegetable Idli",category:"Healthy Indian Breakfasts",protein:12,cal:245,carbs:42,fiber:5,fat:5,mins:25,prep:10,cook:15,ingredients:["6 small prepared idlis (about 250 g)","½ cup finely chopped mixed vegetables","1 tsp oil","½ tsp mustard seeds","¼ tsp urad dal","6 curry leaves","¼ tsp turmeric","¼ tsp sambar powder","1 tbsp chopped coriander","Lemon juice and salt"],steps:["Cut idlis into quarters; if freshly steamed, cool them first so they hold their shape.","Heat oil in a wide pan. Add mustard seeds, urad dal and curry leaves.","Add vegetables, turmeric and a splash of water. Cover and cook 3–4 minutes until just tender.","Add idli pieces and sambar powder. Toss gently over low heat until hot throughout.","Finish with coriander and lemon. Serve with sambar for extra protein and fibre."],note:"Use fermented, egg-free idlis. For a higher-protein plate, serve with a generous bowl of lentil-rich sambar.",vegan:true},
{id:34,name:"Sattu Savoury Breakfast Drink",category:"Healthy Indian Breakfasts",protein:18,cal:235,carbs:29,fiber:8,fat:6,mins:8,prep:8,cook:0,ingredients:["½ cup roasted chana sattu","1½ cups chilled water","2 tbsp finely chopped cucumber","1 tbsp chopped coriander","1 tbsp lemon juice","¼ tsp roasted cumin powder","Pinch of black salt","Black pepper and mint to taste"],steps:["Add sattu to a large jug. Pour in about ½ cup water gradually while whisking to prevent lumps.","Whisk in the remaining water until smooth and drinkable.","Stir in cucumber, coriander, lemon, cumin, black salt and pepper.","Taste and adjust lemon and seasoning. Serve immediately over ice if desired."],note:"A no-cook option. Check the sattu label for cross-contact warnings if preparing for someone with food allergies.",vegan:true},
{id:35,name:"Paneer Spinach Breakfast Wrap",category:"Healthy Indian Breakfasts",protein:24,cal:340,carbs:34,fiber:7,fat:13,mins:20,prep:8,cook:12,ingredients:["2 small whole-wheat rotis","120 g low-fat paneer, crumbled","1 cup chopped spinach","2 tbsp chopped onion","½ tomato, chopped","1 tsp oil","¼ tsp cumin","¼ tsp turmeric","Black pepper and lemon"],steps:["Heat oil in a skillet; add cumin and onion and cook 2 minutes.","Add tomato, turmeric and pepper; cook until softened.","Add spinach and cook until wilted. Fold in crumbled paneer and warm for 2–3 minutes.","Season with lemon and a pinch of salt. Divide filling between the two warm rotis.","Roll tightly and toast seam-side down for 30 seconds. Serve warm."],note:"Vegetarian, not vegan. Use low-fat paneer and whole-wheat rotis; nutrition estimate includes both wraps.",vegan:false},
{id:36,name:"Methi Tofu Paratha",category:"Healthy Indian Breakfasts",protein:19,cal:315,carbs:39,fiber:7,fat:9,mins:30,prep:15,cook:15,ingredients:["1 cup whole-wheat flour","100 g firm tofu, finely crumbled","½ cup chopped fresh methi","¼ tsp ajwain","¼ tsp cumin powder","¼ tsp chilli powder","¼ tsp turmeric","½ tsp oil for dough","2 tsp oil for cooking","Water and salt"],steps:["Mix flour, tofu, methi, ajwain, cumin, chilli, turmeric, salt and ½ tsp oil.","Add water a little at a time and knead into a soft, pliable dough. Rest covered 10 minutes.","Divide into four balls. Roll each between lightly floured sheets into a small paratha.","Cook on a hot tawa, turning once bubbles appear. Brush each side lightly with oil.","Cook until brown spots appear and the centre is cooked. Serve with plain soy yogurt or raita."],note:"Tofu adds moisture, so add water gradually. Vegan when served without dairy accompaniments.",vegan:true},
{id:37,name:"Masala Oats with Soy Chunks",category:"Healthy Indian Breakfasts",protein:24,cal:320,carbs:40,fiber:9,fat:8,mins:22,prep:8,cook:14,ingredients:["½ cup rolled oats","25 g dry soy chunks","½ cup diced vegetables","2 tbsp chopped onion","1 tsp oil","½ tsp cumin seeds","¼ tsp turmeric","½ tsp coriander powder","2 cups water","Lemon, coriander and salt"],steps:["Soak soy chunks in boiling water for 10 minutes. Drain, rinse and squeeze firmly; chop into bite-size pieces.","Heat oil in a saucepan. Add cumin and onion; cook 2 minutes.","Add vegetables, soy chunks and spices; stir for 2 minutes.","Add water and bring to a simmer. Stir in oats and cook 5–7 minutes until creamy.","Finish with lemon and coriander. Adjust consistency with hot water and serve."],note:"Soy chunks vary by brand; nutrition estimate assumes plain defatted soy chunks.",vegan:true},
{id:38,name:"Vegetable Dalia Khichdi",category:"Healthy Indian Breakfasts",protein:14,cal:295,carbs:48,fiber:9,fat:6,mins:30,prep:10,cook:20,ingredients:["½ cup broken wheat (dalia)","¼ cup split moong dal, rinsed","1 cup mixed diced vegetables","½ small tomato, chopped","1 tsp oil","½ tsp cumin seeds","¼ tsp turmeric","3 cups water","Salt, ginger and coriander"],steps:["Rinse dalia and moong dal. Drain well.","Heat oil in a pressure cooker or heavy saucepan. Add cumin and ginger.","Add tomato, vegetables, dalia, moong dal, turmeric, salt and water.","Pressure-cook for 2 whistles, then allow pressure to release naturally; or simmer covered 20–25 minutes, stirring occasionally.","Check both grains are tender. Add hot water for a softer khichdi and finish with coriander."],note:"Contains wheat and is not gluten-free. For a gluten-free version, use millet in place of dalia and adjust the liquid.",vegan:true},
{id:39,name:"Chana Dal and Lauki Pancakes",category:"Healthy Indian Breakfasts",protein:17,cal:285,carbs:38,fiber:9,fat:7,mins:30,prep:15,cook:15,ingredients:["½ cup chana dal, soaked 3 hours","½ cup grated bottle gourd, squeezed lightly","1 tbsp rice flour","½ tsp grated ginger","¼ tsp cumin","2 tbsp coriander","1 small green chilli, optional","2 tsp oil","Salt"],steps:["Drain soaked chana dal and blend with ginger and 3–4 tbsp water to a coarse batter.","Stir in grated lauki, rice flour, cumin, coriander, chilli and salt.","Heat a non-stick skillet and brush lightly with oil.","Spoon batter into two small pancakes and flatten gently. Cover and cook 3–4 minutes over medium-low heat.","Flip carefully and cook another 3 minutes until cooked through. Repeat with remaining batter."],note:"Squeeze excess lauki liquid only lightly; the moisture helps keep the pancakes tender.",vegan:true},
{id:40,name:"Tomato Tofu Breakfast Toast",category:"Healthy Indian Breakfasts",protein:20,cal:305,carbs:35,fiber:8,fat:10,mins:15,prep:7,cook:8,ingredients:["2 slices whole-grain bread","150 g firm tofu, crumbled","1 medium tomato, chopped","1 cup baby spinach","1 tsp olive oil","¼ tsp smoked paprika","¼ tsp cumin","Black pepper, lemon and salt"],steps:["Toast bread until crisp. Pat tofu dry and crumble.","Heat oil in a skillet. Add cumin and tomato; cook 3 minutes until jammy.","Add tofu, paprika and black pepper. Cook 3 minutes, stirring to coat.","Fold in spinach and cook until wilted. Season with lemon and a little salt.","Pile the tofu mixture onto toast and serve immediately."],note:"Choose whole-grain bread with no honey or dairy for a vegan meal.",vegan:true},
{id:41,name:"Rava Vegetable Idli",category:"Healthy Indian Breakfasts",protein:13,cal:270,carbs:43,fiber:5,fat:6,mins:25,prep:10,cook:15,ingredients:["1 cup fine semolina (rava)","½ cup plain unsweetened soy yogurt","¼–½ cup water","½ cup grated carrot and peas","½ tsp mustard seeds","½ tsp oil","¼ tsp baking soda or ½ tsp fruit salt","Curry leaves, coriander and salt"],steps:["Dry-roast semolina over low heat for 3–4 minutes; cool completely.","Mix soy yogurt, semolina, vegetables, salt and enough water to make a thick spoonable batter. Rest 8 minutes.","Prepare a steamer and lightly grease idli moulds. Just before steaming, fold in baking soda or fruit salt.","Fill moulds two-thirds full and steam 10–12 minutes, until a skewer comes out clean.","Rest 2 minutes before unmoulding. Serve with sambar or coconut chutney."],note:"This vegan adaptation uses soy yogurt. Traditional rava idli often contains dairy; check the semolina and raising-agent labels.",vegan:true},
{id:42,name:"Peanut-Free Millet Pongal",category:"Healthy Indian Breakfasts",protein:15,cal:300,carbs:47,fiber:8,fat:8,mins:30,prep:10,cook:20,ingredients:["½ cup little millet, rinsed","¼ cup split yellow moong dal, rinsed","3 cups water","1 tsp oil","½ tsp cumin seeds","½ tsp crushed black pepper","½ tsp grated ginger","8 curry leaves","¼ tsp turmeric","Salt"],steps:["Dry-toast moong dal in a saucepan for 2 minutes until aromatic; do not brown deeply.","Add rinsed millet, water, turmeric and salt. Bring to a boil.","Cover and simmer 18–20 minutes, stirring once or twice, until millet and dal are soft. Add hot water if needed.","Warm oil in a small pan. Add cumin, pepper, ginger and curry leaves; sizzle briefly.","Pour tempering over pongal and stir. Serve soft and hot with sambar."],note:"A nut-free, dairy-free pongal. Millet cooking times vary; follow the package if it differs.",vegan:true},
{id:43,name:"Black Chana Breakfast Sundal",category:"Healthy Indian Breakfasts",protein:17,cal:280,carbs:42,fiber:11,fat:6,mins:15,prep:5,cook:10,ingredients:["1½ cups cooked kala chana","½ tsp oil","½ tsp mustard seeds","6 curry leaves","¼ tsp turmeric","1 tbsp grated fresh coconut, optional","1 tbsp lemon juice","2 tbsp chopped coriander","Pinch of hing and salt"],steps:["If using freshly cooked kala chana, drain but reserve a little cooking liquid.","Heat oil in a pan. Add mustard seeds, curry leaves and hing.","Add turmeric and cooked chana with 1–2 tbsp reserved liquid. Toss over medium heat for 3–4 minutes.","Turn off the heat. Add lemon, coriander and optional coconut.","Taste and serve warm or at room temperature."],note:"Use no coconut if avoiding it; the recipe remains satisfying with lemon and coriander.",vegan:true},
{id:44,name:"Sweet Potato Besan Pancakes",category:"Healthy Indian Breakfasts",protein:15,cal:290,carbs:40,fiber:7,fat:8,mins:25,prep:10,cook:15,ingredients:["½ cup besan","½ cup cooked mashed sweet potato","¼ cup water, approximately","2 tbsp chopped spinach","¼ tsp cumin powder","¼ tsp turmeric","½ tsp grated ginger","2 tsp oil","Salt and black pepper"],steps:["Whisk besan with water, cumin, turmeric, ginger, salt and pepper to make a thick batter.","Fold in mashed sweet potato and chopped spinach until evenly combined.","Heat a non-stick pan over medium-low and brush with a little oil.","Spoon batter into four small pancakes and flatten to about 1 cm thick.","Cook 3–4 minutes per side until golden and set in the centre. Serve warm with unsweetened soy yogurt."],note:"Make small pancakes so the sweet-potato centre cooks before the outside over-browns.",vegan:true},
{id:45,name:"Protein-Rich Savoury Soy Yogurt Bowl",category:"Healthy Indian Breakfasts",protein:22,cal:265,carbs:27,fiber:8,fat:8,mins:10,prep:10,cook:0,ingredients:["1 cup plain unsweetened high-protein soy yogurt","½ cup cooked chickpeas, rinsed and drained","½ cup diced cucumber","¼ cup grated carrot","1 tbsp pumpkin seeds","½ tsp roasted cumin powder","1 tbsp lemon juice","2 tbsp chopped mint and coriander","Black pepper and salt"],steps:["Spoon soy yogurt into two serving bowls and whisk until creamy.","Pat chickpeas dry and season with cumin, pepper and a little salt.","Top yogurt with chickpeas, cucumber and carrot.","Add pumpkin seeds, herbs and lemon juice.","Serve immediately; keep chilled until serving."],note:"Choose unsweetened soy yogurt with a higher protein content; brands vary considerably.",vegan:true}
];
expandedRecipes.splice(0,20,...curatedBreakfasts);
const curatedProteinBreakfasts = [
{id:46,name:"Andhra Pesarattu with Ginger Chutney",category:"Protein-Rich Breakfasts",protein:17,cal:290,carbs:43,fiber:9,fat:6,mins:30,prep:10,cook:20,ingredients:["1 cup whole green moong, rinsed and soaked 4–6 hours","2 tbsp rice (optional)","1 inch ginger, chopped","1 green chilli","½ tsp cumin seeds","2 tbsp coriander leaves","½ small onion, finely chopped","2 tsp oil","Salt to taste"],steps:["Drain soaked moong and rice. Blend with ginger, chilli, cumin, coriander, salt and enough water to make a smooth, pourable batter.","Heat a seasoned tawa over medium-high. Lightly wipe with oil.","Pour a ladle of batter and spread into a thin circle. Sprinkle with chopped onion.","Cook until the underside is crisp and the top looks dry, about 2–3 minutes. Flip briefly if needed.","Repeat with remaining batter. Serve with ginger chutney; omit ghee to keep it vegan."],note:"Traditional Andhra-style green gram dosa. Soaking time is not included in the active preparation estimate.",vegan:true},
{id:47,name:"Paneer and Spinach Stuffed Besan Chilla",category:"Protein-Rich Breakfasts",protein:25,cal:355,carbs:34,fiber:7,fat:14,mins:25,prep:10,cook:15,ingredients:["¾ cup besan","½ cup water, approximately","100 g low-fat paneer, crumbled","1 cup chopped spinach","2 tbsp chopped onion","¼ tsp ajwain","¼ tsp turmeric","½ tsp cumin powder","2 tsp oil","Coriander, chilli and salt"],steps:["Whisk besan, water, ajwain, turmeric, cumin and salt into a smooth batter; rest 5 minutes.","Wilt spinach in a dry pan for 1–2 minutes. Cool, squeeze lightly and mix with paneer, onion and coriander.","Heat a non-stick pan and brush with a little oil. Pour half the batter and spread into a thin round.","Cook until the top sets, flip, add half the paneer-spinach filling to one side and fold over.","Cook 1 minute more to warm the filling. Repeat with remaining batter and serve."],note:"Vegetarian, not vegan. Protein estimate depends on paneer brand and besan quantity.",vegan:false},
{id:48,name:"Soya Keema Breakfast Lettuce-Free Wrap",category:"Protein-Rich Breakfasts",protein:27,cal:330,carbs:34,fiber:8,fat:9,mins:25,prep:10,cook:15,ingredients:["35 g dry soy granules","2 small whole-wheat rotis","½ cup finely diced capsicum","¼ cup chopped onion","½ tomato, chopped","1 tsp oil","¼ tsp cumin seeds","½ tsp coriander powder","¼ tsp garam masala","Ginger, chilli, lemon and salt"],steps:["Cover soy granules with boiling water for 8–10 minutes. Drain, rinse and squeeze firmly.","Heat oil in a skillet. Add cumin and onion; cook until softened.","Add tomato, capsicum, ginger and spices. Cook 3–4 minutes.","Stir in soy granules with 2 tbsp water. Cook 5 minutes until flavours combine and mixture is fairly dry.","Spoon into warm rotis, add lemon and coriander, then roll tightly."],note:"Contains soy and wheat. Check the soy granules label for protein content; values vary by brand.",vegan:true},
{id:49,name:"Hung Curd Cucumber and Chana Bowl",category:"Protein-Rich Breakfasts",protein:22,cal:295,carbs:32,fiber:7,fat:8,mins:10,prep:10,cook:0,ingredients:["200 g plain low-fat Greek yogurt or hung curd","½ cup cooked chickpeas, drained","½ cup diced cucumber","¼ cup grated carrot","½ tsp roasted cumin powder","1 tbsp lemon juice","2 tbsp mint and coriander","1 tbsp pumpkin seeds","Black pepper and salt"],steps:["Whisk yogurt until smooth with lemon juice, cumin, pepper and salt.","Pat chickpeas dry and toss with a little cumin and chopped herbs.","Divide yogurt between two bowls. Top with chickpeas, cucumber and carrot.","Sprinkle with pumpkin seeds and remaining herbs.","Serve chilled. Keep refrigerated until serving."],note:"Vegetarian, not vegan. Use plain unsweetened yogurt; protein content varies significantly between Greek-yogurt brands.",vegan:false},
{id:50,name:"Tofu Akuri with Tomato and Coriander",category:"Protein-Rich Breakfasts",protein:22,cal:285,carbs:18,fiber:5,fat:15,mins:18,prep:7,cook:11,ingredients:["200 g firm tofu, drained and crumbled","¼ onion, finely chopped","1 small tomato, finely chopped","½ green chilli, minced","½ tsp grated ginger","¼ tsp turmeric","¼ tsp cumin seeds","¼ tsp ground coriander","1 tsp oil","2 tbsp coriander leaves and lemon"],steps:["Press tofu between paper towels for 5 minutes and crumble roughly.","Heat oil in a skillet. Add cumin, onion, ginger and chilli; cook 2 minutes.","Add tomato, turmeric and ground coriander. Cook until tomato softens.","Fold in tofu and cook 4–5 minutes, stirring gently until hot and lightly dry.","Finish with coriander and lemon. Serve with whole-grain toast or roti."],note:"A plant-based adaptation of the softly scrambled Parsi-style akuri idea; no eggs or dairy are used.",vegan:true},
{id:51,name:"Soya Chunk and Vegetable Upma",category:"Protein-Rich Breakfasts",protein:23,cal:315,carbs:42,fiber:8,fat:7,mins:25,prep:10,cook:15,ingredients:["25 g dry soy chunks, finely chopped after soaking","½ cup semolina (rava)","½ cup diced carrot, peas and beans","2 tbsp chopped onion","1 tsp oil","½ tsp mustard seeds","½ tsp urad dal","6 curry leaves","2 cups hot water","Ginger, lemon and salt"],steps:["Soak soy chunks in boiling water 10 minutes. Drain, rinse, squeeze dry and chop finely.","Dry-roast semolina in a pan for 3 minutes; transfer to a plate.","Heat oil; add mustard seeds, urad dal and curry leaves. Add onion, ginger and vegetables; cook 3 minutes.","Add chopped soy and stir for 2 minutes. Pour in hot water and bring to a simmer.","Rain in semolina while stirring. Cover and cook on low 4–5 minutes until fluffy. Finish with lemon."],note:"Contains wheat and soy. Stir semolina in gradually to avoid lumps.",vegan:true},
{id:52,name:"Quinoa Moong Dal Breakfast Pongal",category:"Protein-Rich Breakfasts",protein:17,cal:305,carbs:45,fiber:8,fat:7,mins:30,prep:8,cook:22,ingredients:["½ cup quinoa, rinsed very well","¼ cup split yellow moong dal, rinsed","3 cups water","½ tsp cumin seeds","½ tsp black pepper, crushed","½ tsp grated ginger","8 curry leaves","1 tsp oil","¼ tsp turmeric","Salt"],steps:["Dry-toast moong dal for 2 minutes in a saucepan until fragrant.","Add quinoa, water, turmeric and salt. Bring to a boil.","Cover and simmer 18–20 minutes, stirring occasionally, until quinoa opens and dal is soft.","Heat oil in a small pan. Add cumin, pepper, ginger and curry leaves; sizzle briefly.","Stir tempering into the pongal. Add hot water to loosen if needed and serve warm."],note:"Quinoa should be rinsed to remove surface saponins. Protein estimate is per serving.",vegan:true},
{id:53,name:"Paneer and Peas Breakfast Paratha",category:"Protein-Rich Breakfasts",protein:23,cal:390,carbs:43,fiber:7,fat:13,mins:35,prep:20,cook:15,ingredients:["1 cup whole-wheat flour","100 g low-fat paneer, crumbled","½ cup green peas, cooked and mashed","½ tsp cumin powder","¼ tsp amchur","¼ tsp chilli powder","2 tbsp chopped coriander","2 tsp oil for cooking","Water and salt"],steps:["Knead flour with a pinch of salt and enough water into a soft dough. Cover and rest 10 minutes.","Mix paneer, mashed peas, cumin, amchur, chilli and coriander. Season lightly.","Divide dough into four balls. Roll two into small discs.","Place filling on one disc, cover with another and seal edges; dust lightly with flour.","Roll gently and cook on a hot tawa, brushing each side with a little oil, until golden and cooked through."],note:"Vegetarian, not vegan. Makes two generously stuffed parathas; serve with plain yogurt if desired.",vegan:false},
{id:54,name:"Moong Sprout and Tofu Chaat",category:"Protein-Rich Breakfasts",protein:21,cal:280,carbs:33,fiber:10,fat:8,mins:18,prep:8,cook:10,ingredients:["1 cup mung bean sprouts","120 g firm tofu, cubed","½ cup diced tomato","½ cup diced cucumber","2 tbsp chopped onion","1 tsp oil","½ tsp roasted cumin powder","½ tsp chaat masala","1 tbsp lemon juice","Coriander and salt"],steps:["Steam or boil sprouts for 5–7 minutes until thoroughly hot and tender; drain well.","Pat tofu dry. Heat oil in a non-stick pan and lightly brown tofu cubes on two sides.","Combine warm sprouts, tofu, tomato, cucumber and onion in a bowl.","Season with cumin, chaat masala, lemon and salt; toss gently.","Finish with coriander and serve promptly."],note:"Cook sprouts thoroughly rather than serving raw, particularly for people at higher risk of foodborne illness.",vegan:true},
{id:55,name:"Masala Dhokla with Extra Chana Dal",category:"Protein-Rich Breakfasts",protein:14,cal:265,carbs:42,fiber:6,fat:6,mins:30,prep:10,cook:20,ingredients:["¾ cup besan","2 tbsp chana dal flour","½ cup plain unsweetened soy yogurt","¼ cup water, as needed","½ tsp ginger-chilli paste","½ tsp fruit salt (eno)","½ tsp mustard seeds","1 tsp oil","6 curry leaves","1 tbsp sesame seeds, optional","Lemon and coriander"],steps:["Whisk besan, chana dal flour, soy yogurt, ginger-chilli paste and water into a smooth thick batter.","Rest 5 minutes while bringing steamer water to a steady boil. Grease a shallow steaming tray.","Just before steaming, fold fruit salt into batter with one quick motion; transfer immediately to tray.","Steam covered 12–15 minutes until a skewer inserted in the centre comes out clean.","Heat oil; crackle mustard seeds and curry leaves, add a splash of water and lemon, then spoon over dhokla. Cool slightly and cut."],note:"Vegan adaptation using soy yogurt; verify fruit salt ingredients. Steam time depends on tray depth.",vegan:true},
{id:56,name:"Mixed Lentil Adai with Spinach",category:"Protein-Rich Breakfasts",protein:19,cal:320,carbs:43,fiber:10,fat:8,mins:30,prep:10,cook:20,ingredients:["¼ cup each chana dal, toor dal and split yellow moong dal","2 tbsp rice","1 dried red chilli","½ tsp cumin seeds","½ cup finely chopped spinach","2 tbsp chopped coriander","¼ tsp hing (check gluten-free label if needed)","2 tsp oil","Salt and water"],steps:["Rinse dals and rice. Soak with dried chilli for 3–4 hours, then drain.","Grind coarsely with cumin, hing, salt and enough water to make a thick spreadable batter.","Stir in spinach and coriander. Rest 5 minutes.","Heat a tawa, brush with oil and spread a ladle of batter into a thick 15 cm disc. Make a small hole in the centre for even cooking.","Cook 3–4 minutes per side until golden and cooked through. Repeat with remaining batter."],note:"Naturally vegan when cooked with oil. Soaking time is additional to the active preparation estimate.",vegan:true},
{id:57,name:"High-Protein Savoury Overnight Oats",category:"Protein-Rich Breakfasts",protein:20,cal:310,carbs:38,fiber:8,fat:9,mins:10,prep:10,cook:0,ingredients:["½ cup rolled oats","¾ cup plain unsweetened high-protein soy milk","½ cup plain unsweetened soy yogurt","1 tbsp chia seeds","½ cup grated cucumber","¼ cup grated carrot","½ tsp roasted cumin powder","1 tbsp lemon juice","2 tbsp chopped mint","1 tbsp pumpkin seeds"],steps:["Combine oats, soy milk, soy yogurt and chia in a lidded container.","Cover and refrigerate at least 6 hours or overnight.","In the morning, stir well; add a splash of soy milk if too thick.","Fold in cucumber, carrot, cumin, lemon and mint.","Top with pumpkin seeds and serve chilled. Keep refrigerated until eating."],note:"Use unsweetened fortified soy milk and yogurt. Nutrition depends on the protein content of the brands selected.",vegan:true},
{id:58,name:"Chickpea and Tofu Breakfast Sandwich",category:"Protein-Rich Breakfasts",protein:24,cal:360,carbs:39,fiber:9,fat:12,mins:18,prep:8,cook:10,ingredients:["2 slices whole-grain bread","½ cup cooked chickpeas, lightly mashed","100 g firm tofu, crumbled","¼ tomato, finely chopped","2 tbsp chopped onion","½ tsp smoked paprika","¼ tsp cumin powder","1 tsp olive oil","Lemon, coriander and black pepper"],steps:["Toast bread lightly. Pat tofu dry and crumble.","Heat oil in a skillet. Add onion and tomato; cook 2–3 minutes.","Add chickpeas, tofu, paprika, cumin and pepper. Mash some chickpeas as the mixture warms.","Cook 4–5 minutes until the filling is hot and holds together; finish with lemon and coriander.","Divide filling between toast slices, close the sandwiches and serve."],note:"Check bread ingredients for dairy or honey if keeping the meal vegan.",vegan:true},
{id:59,name:"Ragi Tofu Vegetable Uttapam",category:"Protein-Rich Breakfasts",protein:17,cal:300,carbs:43,fiber:7,fat:8,mins:25,prep:10,cook:15,ingredients:["¾ cup ragi flour","¼ cup rice flour","100 g firm tofu, finely crumbled","½ cup plain unsweetened soy yogurt","½ cup water, approximately","¼ cup chopped onion","¼ cup chopped tomato","2 tbsp coriander","½ tsp cumin","2 tsp oil","Salt"],steps:["Whisk ragi flour, rice flour, soy yogurt, water, cumin and salt into a thick batter. Rest 8 minutes.","Fold in crumbled tofu. Adjust batter so it spreads slowly but does not run.","Heat a non-stick tawa over medium-low and brush with a little oil.","Pour batter into two small thick pancakes. Top with onion, tomato and coriander; press toppings lightly.","Cover and cook 3–4 minutes, flip carefully and cook another 2–3 minutes until centre is set."],note:"Vegan and egg-free. This is an instant batter adaptation; texture differs from fermented rice-urad uttapam.",vegan:true},
{id:60,name:"Kala Chana and Sweet Potato Breakfast Bowl",category:"Protein-Rich Breakfasts",protein:17,cal:315,carbs:49,fiber:11,fat:7,mins:20,prep:8,cook:12,ingredients:["1 cup cooked kala chana","150 g sweet potato, cubed and steamed","½ cup diced cucumber","¼ cup diced tomato","1 tbsp lemon juice","½ tsp roasted cumin powder","¼ tsp chaat masala","2 tbsp coriander","1 tbsp pumpkin seeds","Salt and pepper"],steps:["Steam sweet potato cubes until just tender, about 8–10 minutes; cool slightly.","Warm cooked kala chana in a small pan with a splash of water, cumin and chaat masala.","Divide chana and sweet potato between two bowls.","Add cucumber, tomato, lemon and coriander.","Top with pumpkin seeds and serve warm or at room temperature."],note:"Cooked kala chana can be batch-prepared and refrigerated promptly. No nuts or dairy.",vegan:true},
{id:61,name:"Paneer and Capsicum Breakfast Toastie",category:"Protein-Rich Breakfasts",protein:22,cal:350,carbs:34,fiber:6,fat:13,mins:15,prep:7,cook:8,ingredients:["4 small whole-grain bread slices","120 g low-fat paneer, crumbled","¼ red capsicum, finely diced","2 tbsp chopped onion","¼ tsp cumin powder","¼ tsp chilli flakes","1 tbsp coriander chutney (egg-free)","1 tsp oil for pan"],steps:["Mix paneer, capsicum, onion, cumin, chilli and coriander chutney.","Spread filling over two bread slices and close with the remaining slices.","Heat a non-stick skillet or sandwich press; brush the outside lightly with oil.","Toast over medium-low heat, pressing gently, until crisp and the filling is hot.","Cut in half and serve immediately."],note:"Vegetarian, not vegan. Check bread and chutney labels for egg-free ingredients.",vegan:false},
{id:62,name:"Sattu and Roasted Chana Savoury Bowl",category:"Protein-Rich Breakfasts",protein:20,cal:290,carbs:38,fiber:10,fat:7,mins:10,prep:10,cook:0,ingredients:["½ cup roasted chana sattu","½ cup cooked chickpeas","1 cup chilled water","½ cup diced cucumber","¼ cup diced tomato","1 tbsp lemon juice","½ tsp roasted cumin","2 tbsp coriander and mint","Black salt and pepper"],steps:["Whisk sattu with water gradually until smooth and thick like a savoury porridge.","Season with lemon, cumin, black salt and pepper.","Fold in chickpeas, cucumber and tomato.","Add chopped herbs and stir. Adjust thickness with a little water if needed.","Serve immediately, chilled or at room temperature."],note:"A no-cook savoury breakfast inspired by Bihari sattu preparations. Use plain roasted chana flour, not sweetened drink mix.",vegan:true},
{id:63,name:"Moong Dal Idli with Vegetable Sambar",category:"Protein-Rich Breakfasts",protein:18,cal:315,carbs:48,fiber:10,fat:6,mins:35,prep:15,cook:20,ingredients:["½ cup split yellow moong dal, soaked 2 hours","¼ cup idli rice, soaked 2 hours","¼ tsp fenugreek seeds","½ cup grated carrot and chopped spinach","½ tsp salt","For quick sambar: ¼ cup cooked toor dal, ½ cup mixed vegetables, 1 tsp sambar powder, tamarind water"],steps:["Drain moong, rice and fenugreek. Blend with a little water to a thick batter.","Fold in carrot, spinach and salt. Rest 10 minutes; this is an instant idli, not a fermented batter.","Grease idli moulds and fill two-thirds full. Steam 12–15 minutes until a skewer comes out clean.","For sambar, simmer cooked toor dal, vegetables, sambar powder and tamarind water until vegetables are tender.","Serve two idlis per person with a bowl of hot sambar."],note:"Protein estimate includes the sambar portion. Steam thoroughly; cooking time depends on mould size.",vegan:true},
{id:64,name:"Tofu and Mushroom Masala Breakfast Quesadilla",category:"Protein-Rich Breakfasts",protein:23,cal:345,carbs:34,fiber:7,fat:13,mins:20,prep:8,cook:12,ingredients:["2 medium whole-wheat tortillas","150 g firm tofu, crumbled","1 cup sliced mushrooms","¼ cup diced capsicum","2 tbsp chopped onion","½ tsp smoked paprika","¼ tsp cumin","1 tsp olive oil","2 tbsp salsa, egg-free","Lime and coriander"],steps:["Pat tofu dry. Heat oil in a skillet and cook mushrooms until their moisture evaporates.","Add onion, capsicum, cumin and paprika; cook 2 minutes.","Add tofu and cook 4 minutes until lightly golden. Finish with lime and coriander.","Divide filling over half of each tortilla; spoon on salsa and fold closed.","Toast in a dry skillet 2 minutes per side until crisp and hot. Cut into wedges."],note:"Vegan if tortillas and salsa contain no dairy or honey. Check labels.",vegan:true},
{id:65,name:"Cinnamon Soy Yogurt Oat Bowl",category:"Protein-Rich Breakfasts",protein:21,cal:325,carbs:42,fiber:8,fat:9,mins:10,prep:10,cook:0,ingredients:["¾ cup plain unsweetened high-protein soy yogurt","⅓ cup rolled oats","½ cup diced apple","1 tbsp chia seeds","1 tbsp pumpkin seeds","½ tsp cinnamon","1 tsp lemon juice","2–3 tbsp unsweetened soy milk"],steps:["Stir oats, soy yogurt and soy milk together in a bowl.","Fold in chia and cinnamon; rest 5 minutes to soften the oats.","Add diced apple tossed with lemon juice.","Top with pumpkin seeds and serve, or refrigerate overnight for a softer texture.","Keep chilled until serving."],note:"Choose unsweetened soy yogurt with a protein-rich label. No nuts, dairy or added sugar.",vegan:true}
];
expandedRecipes.splice(20,20,...curatedProteinBreakfasts);
recipes.push(...expandedRecipes.slice(0,275));
// Attach representative food photography and appliance timing metadata to the original recipes.
recipes.forEach((r,i)=>{ r.image="https://loremflickr.com/900/600/vegetarian,food?lock="+r.id; if(!r.prep) r.prep=Math.max(5,Math.round(r.mins*.35)); if(!r.cook) r.cook=r.mins-r.prep; if(r.vegan===undefined) r.vegan=![15,18].includes(r.id); });

renderFilters();renderRecipes();renderPlanner();updateTracker();

async function loadIndividualRecipeFiles(){
 try{
  const manifest=await fetch("recipes/manifest.json").then(r=>{if(!r.ok)throw new Error("manifest unavailable");return r.json();});
  const records=await Promise.all(manifest.recipes.map(path=>fetch(path).then(r=>{if(!r.ok)throw new Error("Could not load "+path);return r.json();})));
  for(const record of records){
   const normalized={...record,cal:record.cal??record.calories??0,mins:record.mins??((record.prep||0)+(record.cook||0)),prep:record.prep??10,cook:record.cook??Math.max(5,(record.mins||25)-10),fiber:record.fiber??record.fibre??0};
   const at=recipes.findIndex(x=>x.id===record.id);
   if(at>=0)recipes[at]=normalized;else recipes.push(normalized);
  }
  renderFilters();renderRecipes();renderPlanner();updateTracker();
 }catch(error){console.error("Individual recipe records could not be loaded:",error);}
}
loadIndividualRecipeFiles();
